from collections import deque
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
def bfs(start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order
print(bfs("A"))

