def binary_search(values, target):
    low, high = 0, len(values) - 1
    while low <= high:
        middle = (low + high) // 2
        if values[middle] == target:
            return middle
        if values[middle] < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1
def fib(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    dp = [0, 1]
    for _ in range(2, n + 1):
        dp.append(dp[-1] + dp[-2])
    return dp[n]
